# =============================================================================
# HELPER FUNCTIONS
# =============================================================================

def _flatten_children(children):
    """Recursively flatten React children tree for traversal."""
    if children is None:
        return []
    if isinstance(children, (list, tuple)):
        result = []
        for child in children:
            result.extend(_flatten_children(child))
        return result
    if isinstance(children, dict) and 'props' in children:
        # Single React element
        result = [children]
        nested = children.get('props', {}).get('children')
        result.extend(_flatten_children(nested))
        return result
    return [children]


